package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.*;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class Cleaner_clean_TriageGen0Test {

    @Test
    public void testClean_NullInput_ThrowsException() {
        Cleaner cleaner = new Cleaner(Safelist.basic());
        try {
            cleaner.clean(null);
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // Expected
        }
    }

    @Test
    public void testClean_SimpleHtml_ReturnsCleanDocument() {
        Cleaner cleaner = new Cleaner(Safelist.basic());
        Document dirty = Jsoup.parse("<p>Hello <b>World</b></p>");

        Document clean = cleaner.clean(dirty);

        assertNotNull(clean);
        assertEquals(dirty.baseUri(), clean.baseUri());
        assertEquals("<p>Hello <b>World</b></p>", clean.body().html());
    }

    @Test
    public void testClean_UnsafeHtml_RemovesUnsafeTags() {
        // Safelist.basic() allows <p>, <b>, etc., but not <script>
        Cleaner cleaner = new Cleaner(Safelist.basic());
        Document dirty = Jsoup.parse("<div><p>Safe</p><script>alert('xss')</script></div>");

        Document clean = cleaner.clean(dirty);

        // Note: Jsoup Cleaner removes the element itself if it is not in the whitelist
        // Depending on implementation, <div> might be stripped if not allowed
        String cleanHtml = clean.body().html();
        assertTrue(cleanHtml.contains("<p>Safe</p>"));
        assertTrue(!cleanHtml.contains("<script>"));
    }

    @Test
    public void testClean_PreservesBaseUri() {
        Cleaner cleaner = new Cleaner(Safelist.none());
        Document dirty = Jsoup.parse("<html><head></head><body><p>Text</p></body></html>");
        dirty.setBaseUri("https://example.com/path");

        Document clean = cleaner.clean(dirty);

        assertEquals("https://example.com/path", clean.baseUri());
    }

    @Test
    public void testClean_EmptyDocument() {
        Cleaner cleaner = new Cleaner(Safelist.none());
        Document dirty = Jsoup.parse("");

        Document clean = cleaner.clean(dirty);

        assertNotNull(clean);
        assertEquals("", clean.body().html());
    }

    @Test
    public void testClean_ComplexStructure() {
        Cleaner cleaner = new Cleaner(Safelist.relaxed());
        Document dirty = Jsoup.parse("<ul><li>Item 1</li><li><a href='http://test.com'>Link</a></li></ul>");

        Document clean = cleaner.clean(dirty);

        assertEquals(dirty.body().html(), clean.body().html());
    }

    @Test
    public void testClean_WithAttributes() {
        Cleaner cleaner = new Cleaner(Safelist.basic());
        Document dirty = Jsoup.parse("<p class='text'>Content</p>");

        // Basic safelist usually doesn't allow 'class' attribute unless specified
        Document clean = cleaner.clean(dirty);

        String cleanHtml = clean.body().html();
        assertTrue(cleanHtml.contains("<p>Content</p>"));
        // If 'class' is not in whitelist, it should be removed from the tag
        assertTrue(!cleanHtml.contains("class='text'"));
    }
}
